package acp

import (
	"encoding/json"
	"testing"
)

// BenchmarkUnmarshalJSON_HintedValues decodes messages whose properties
// carry x-deserialize-* hints, so that each hinted value is also checked
// against its shape (see shape.go). The session/new and initialize responses
// are from the Claude Code adapter. The agent message chunk has no value
// that a shape checks.
func BenchmarkUnmarshalJSON_HintedValues(b *testing.B) {
	for _, bm := range []struct {
		name string
		into func() any
		in   string
	}{
		{"session/new response", func() any { return new(NewSessionResponse) }, `{"sessionId":"c090a3c6-f962-49ae-bd60-7c52c9c05650","modes":{"currentModeId":"auto","availableModes":[{"id":"default","name":"Manual","description":"Always ask before making changes"},{"id":"acceptEdits","name":"Accept edits","description":"Automatically accept all file edits"},{"id":"plan","name":"Plan","description":"Create a plan before making changes"},{"id":"auto","name":"Auto","description":"Claude handles permission decisions"},{"id":"bypassPermissions","name":"Bypass permissions","description":"Accepts all permissions"}]},"configOptions":[{"id":"mode","name":"Mode","description":"Session permission mode","category":"mode","type":"select","currentValue":"auto","options":[{"value":"default","name":"Manual","description":"Always ask before making changes"},{"value":"acceptEdits","name":"Accept edits","description":"Automatically accept all file edits"},{"value":"plan","name":"Plan","description":"Create a plan before making changes"},{"value":"auto","name":"Auto","description":"Claude handles permission decisions"},{"value":"bypassPermissions","name":"Bypass permissions","description":"Accepts all permissions"}]},{"id":"model","name":"Model","description":"AI model to use","category":"model","type":"select","currentValue":"default","options":[{"value":"default","name":"Default (recommended)","description":"Opus"},{"value":"opus","name":"Opus 5.5","description":"Opus 5.5 · Best for everyday, complex tasks · $4/$20 per Mtok"},{"value":"fable","name":"Fable 5.2","description":"Fable 5.2 · Most capable for your hardest and longest-running tasks · $8/$40 per Mtok"},{"value":"sonnet","name":"Sonnet 5.5","description":"Sonnet 5.5 · Efficient for routine tasks · $2/$10 per Mtok"},{"value":"haiku","name":"Haiku 5.5","description":"Haiku 5.5 · Fastest for quick answers · $0.10/$0.50 per Mtok ($0.50/$2.50 for prompts over 100k)"}]},{"id":"effort","name":"Effort","description":"Available effort levels for this model","category":"thought_level","type":"select","currentValue":"default","options":[{"value":"default","name":"Default"},{"value":"low","name":"Low"},{"value":"medium","name":"Medium"},{"value":"high","name":"High"},{"value":"xhigh","name":"Xhigh"},{"value":"max","name":"Max"}]},{"id":"fast","name":"Fast mode","description":"Faster responses on supported models","category":"model_config","type":"boolean","currentValue":false},{"id":"ultracode","name":"Ultracode","description":"Dynamic workflows on every task, at any effort level","category":"model_config","type":"boolean","currentValue":false}]}`},
		{"initialize response", func() any { return new(InitializeResponse) }, "{\"protocolVersion\":1,\"agentCapabilities\":{\"_meta\":{\"claudeCode\":{\"promptQueueing\":true},\"authStatus\":{}},\"promptCapabilities\":{\"image\":true,\"embeddedContext\":true},\"mcpCapabilities\":{\"http\":true,\"sse\":true,\"acp\":true},\"auth\":{\"logout\":{},\"status\":{}},\"providers\":{},\"loadSession\":true,\"sessionCapabilities\":{\"additionalDirectories\":{},\"close\":{},\"delete\":{},\"fork\":{},\"list\":{},\"options\":{},\"resume\":{},\"status\":{},\"systemPrompt\":{\"mode\":{\"override\":{}}},\"title\":{}}},\"agentInfo\":{\"name\":\"@agentclientprotocol/claude-agent-acp\",\"title\":\"Claude Agent\",\"version\":\"0.108.0\"},\"authMethods\":[{\"description\":\"Run `claude /login` in the terminal\",\"name\":\"Log in with Claude\",\"id\":\"claude-login\",\"type\":\"terminal\",\"args\":[\"--cli\"]},{\"description\":\"Use Anthropic Console (API usage billing)\",\"name\":\"Anthropic Console\",\"id\":\"console-login\",\"type\":\"terminal\",\"args\":[\"--cli\",\"auth\",\"login\",\"--console\"]}],\"_meta\":{\"steering\":{\"supported\":true}}}"},
		{"tool call update", func() any { return new(SessionNotification) }, `{"sessionId":"s","update":{"sessionUpdate":"tool_call_update","toolCallId":"call_1","status":"completed","content":[{"type":"content","content":{"type":"text","text":"# My Project\n\nThis is a sample project..."}},{"type":"diff","path":"/project/config.json","oldText":"{}","newText":"{\"a\":1}"}],"locations":[{"path":"/project/config.json","line":1}],"rawOutput":{"content":"# My Project"}}}`},
		{"session list", func() any { return new(ListSessionsResponse) }, `{"sessions":[{"sessionId":"s0","cwd":"/work/0","title":"Session 0","updatedAt":"2026-11-18T07:27:30.000Z"},{"sessionId":"s1","cwd":"/work/1","title":"Session 1","updatedAt":"2026-11-18T07:27:30.000Z"},{"sessionId":"s2","cwd":"/work/2","title":"Session 2","updatedAt":"2026-11-18T07:27:30.000Z"},{"sessionId":"s3","cwd":"/work/3","title":"Session 3","updatedAt":"2026-11-18T07:27:30.000Z"},{"sessionId":"s4","cwd":"/work/4","title":"Session 4","updatedAt":"2026-11-18T07:27:30.000Z"},{"sessionId":"s5","cwd":"/work/5","title":"Session 5","updatedAt":"2026-11-18T07:27:30.000Z"},{"sessionId":"s6","cwd":"/work/6","title":"Session 6","updatedAt":"2026-11-18T07:27:30.000Z"},{"sessionId":"s7","cwd":"/work/7","title":"Session 7","updatedAt":"2026-11-18T07:27:30.000Z"},{"sessionId":"s8","cwd":"/work/8","title":"Session 8","updatedAt":"2026-11-18T07:27:30.000Z"},{"sessionId":"s9","cwd":"/work/9","title":"Session 9","updatedAt":"2026-11-18T07:27:30.000Z"},{"sessionId":"s10","cwd":"/work/10","title":"Session 10","updatedAt":"2026-11-18T07:27:30.000Z"},{"sessionId":"s11","cwd":"/work/11","title":"Session 11","updatedAt":"2026-11-18T07:27:30.000Z"},{"sessionId":"s12","cwd":"/work/12","title":"Session 12","updatedAt":"2026-11-18T07:27:30.000Z"},{"sessionId":"s13","cwd":"/work/13","title":"Session 13","updatedAt":"2026-11-18T07:27:30.000Z"},{"sessionId":"s14","cwd":"/work/14","title":"Session 14","updatedAt":"2026-11-18T07:27:30.000Z"},{"sessionId":"s15","cwd":"/work/15","title":"Session 15","updatedAt":"2026-11-18T07:27:30.000Z"},{"sessionId":"s16","cwd":"/work/16","title":"Session 16","updatedAt":"2026-11-18T07:27:30.000Z"},{"sessionId":"s17","cwd":"/work/17","title":"Session 17","updatedAt":"2026-11-18T07:27:30.000Z"},{"sessionId":"s18","cwd":"/work/18","title":"Session 18","updatedAt":"2026-11-18T07:27:30.000Z"},{"sessionId":"s19","cwd":"/work/19","title":"Session 19","updatedAt":"2026-11-18T07:27:30.000Z"}],"nextCursor":null}`},
		{"plan", func() any { return new(SessionNotification) }, `{"sessionId":"s","update":{"sessionUpdate":"plan","entries":[{"content":"Step 0","priority":"high","status":"pending"},{"content":"Step 1","priority":"medium","status":"in_progress"},{"content":"Step 2","priority":"low","status":"completed"},{"content":"Step 3","priority":"high","status":"pending"},{"content":"Step 4","priority":"medium","status":"in_progress"},{"content":"Step 5","priority":"low","status":"completed"},{"content":"Step 6","priority":"high","status":"pending"},{"content":"Step 7","priority":"medium","status":"in_progress"}]}}`},
		{"agent message chunk", func() any { return new(SessionNotification) }, `{"sessionId":"s","update":{"sessionUpdate":"agent_message_chunk","content":{"type":"text","text":"I'll help you with that. Let me start by reading some files."}}}`},
	} {
		bm := bm
		b.Run(bm.name, func(b *testing.B) {
			data := []byte(bm.in)
			b.SetBytes(int64(len(data)))
			b.ReportAllocs()
			for i := 0; i < b.N; i++ {
				if err := json.Unmarshal(data, bm.into()); err != nil {
					b.Fatal(err)
				}
			}
		})
	}
}
